#let schedule-table(accent: C-teal, rows: ()) = {
  table(
    columns: (1.3cm, 1fr),
    inset: (x: 5pt, y: 4.5pt),
    stroke: (x, y) => if y == 0 { none } else { 0.4pt },
    fill: (x, y) => if y == 0 {
      accent
    } else if calc.even(y) { rgb("#e8e8e8") } else { C-white },
    align: (left, left),
    text(size: 8.5pt, weight: 700, fill: C-white)[TIME], text(size: 8.5pt, weight: 700, fill: C-white)[SCHEDULE],
    ..rows.map(r => (
      text(size: 8.5pt, weight: 700, fill: accent)[#r.at(0)],
      text(size: 9pt, fill: C-navy)[#r.at(1)],
    )).flatten()
  )
}

