// day-entry — single row for table of contents
#let day-entry(num: "01", day-color: C-teal, label-en: "", label-zh: "", subtitle: "") = {
  let row = grid(
    columns: (0.3cm, 2.2cm, 1fr, 2.2cm),
    column-gutter: 6pt,
    align: (center, left, left, right),
    box(width: 0.22cm, height: 0.7cm, fill: day-color, radius: 2pt),
    text(size: 10pt, weight: 900, fill: day-color)[#num],
    [
      #text(size: 9pt, weight: 800, fill: C-navy)[#label-en]
      #text(size: 8.5pt, weight: 400, fill: C-muted)[#label-zh]
    ],
    text(size: 8pt, fill: C-muted)[#subtitle],
  );
  let sep = v(4pt) + box(width: 100%, height: 0.4pt, fill: C-muted.lighten(60%)) + v(4pt);
  row + sep
}

