input.new_string:
// ─── GALLERY SECTION: alternating image-left / image-right editorial rows ──
// Each attraction gets a full editorial row: large image + title + prose beside it.
// Alternates image-left / image-right for visual rhythm.

#let attraction-row(
  title: "",
  copy: "",
  img-path: "",
  accent: C-teal,
) = [
  #text(size: 10pt, weight: 900, fill: accent)[#title]
  #v(3pt)
  #box(width: 2cm, height: 1.5pt, fill: accent, radius: 0.75pt)
  #v(5pt)
  #text(size: 8.5pt, fill: C-text)[#copy]
]

#let gallery-section(
  items: (),
  accent: C-teal,
) = {
  let rows = ()
  for (i, item) in items.enumerate() {
    let img-left = calc.even(i)
    let img-w = 7.5cm
    let img-h = 5cm
    let gap = 12pt
    let img-block = box(clip: true, width: img-w, height: img-h)[
      #image(item.at("img", default: ""), width: img-w, height: img-h, fit: "cover")
    ]
    let text-block = attraction-row(
      title: item.at("title", default: ""),
      copy: item.at("copy", default: ""),
      accent: accent,
    )
    rows.push(
      if img-left {
        grid(columns: (img-w, gap, 1fr), align: (top, top, top), img-block, [], text-block)
      } else {
        grid(columns: (1fr, gap, img-w), align: (top, top, top), text-block, [], img-block)
      }
    )
    if i < items.len() - 1 {
      rows.push(v(10pt))
    }
  }
  rows
}

