// Mirrors the cover page pattern: place(float:true, scope:"parent") in background
// renders behind page content so text is always on top.
#let day-page(
  num: "01",
  date: "Monday, June 2",
  title: "",
  subtitle: "",
  accent-color: C-teal,
  image-path: "images/yangmingshan.jpg",
  body: [],
  star: false,
  gallery: none,
