  page(
    paper: "a4",
    margin: (top: 1.6cm, bottom: 1.4cm, x: 1.8cm),
    footer: none,
    background: {
      // Background image: covers entire page including margins
      place(top + left, float: true, scope: "parent", {
        box(width: 100%, height: 100%)[
          #image(image-path, width: 100%, height: 100%, fit: "cover")
        ]
      })
      // Solid background covering full page - hides the background image completely
      // so the content area is clean and readable
      place(top + left, float: true, scope: "parent", {
        box(width: 100%, height: 100%, fill: white)
      })
    }
  )[
    // All content flows normally on top of background
    // Top accent bar - full width
    #box(width: 100%, height: 6pt, fill: accent-color)
    #v(12pt)

    // Day header row: day label + date + star badge
    #grid(
      columns: (auto, 1fr, auto),
      column-gutter: 8pt,
      align: (left, left, right),
      box(
        width: 1.6cm,
        height: 0.55cm,
        fill: accent-color,
        radius: 3pt,
        align(center + horizon)[
          #text(size: 8pt, weight: 800, fill: C-white, tracking: 1pt)[DAY #num]
        ]
      ),
      text(size: 9pt, fill: C-muted, tracking: 1pt)[#date],
      if star [
        #box(radius: 4pt, inset: (x: 8pt, y: 3pt), fill: C-gold)[
          #text(size: 7.5pt, weight: 700, fill: C-navy)[STAR ATTRACTION]
        ]
      ] else [],
    )
    #v(6pt)

    // Title block
    #text(size: 26pt, weight: 900, fill: C-navy, font: "Arial")[#title]
    #v(3pt)
    #text(size: 8.5pt, fill: C-muted, tracking: 0.5pt)[#subtitle]
    #v(12pt)

    // Divider line
    #box(width: 100%, height: 1.5pt, fill: accent-color)
    #v(14pt)

    // Main content
    #body

    // Gallery section - only if provided
    #if gallery != none [
      #v(18pt)
      #box(width: 100%, height: 1pt, fill: accent-color.lighten(60%))
      #v(10pt)
      #text(size: 8pt, weight: 700, fill: accent-color, tracking: 3pt)[ATTRACTIONS]
      #v(8pt)
      #gallery
    ]

    // Bottom accent bar
